<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$events=$pdo->query("SELECT e.id,e.name,e.event_date,e.status,COUNT(r.id) round_count FROM bdc_events e JOIN bdc_scoring_rounds r ON r.event_id=e.id AND r.status<>'archived' GROUP BY e.id,e.name,e.event_date,e.status ORDER BY e.event_date DESC,e.name")->fetchAll();$eventId=(int)($_GET['event_id']??0);$rounds=[];if($eventId>0){$s=$pdo->prepare("SELECT r.id,r.round_type,r.division,r.scoring_mode,r.status FROM bdc_scoring_rounds r WHERE r.event_id=:e AND r.status<>'archived' ORDER BY r.division,FIELD(r.round_type,'heats','semifinal','final'),r.id");$s->execute(['e'=>$eventId]);$rounds=$s->fetchAll();}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Screen Projector | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.card{border:0;border-radius:16px}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../scoring/">BDC Scoring</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4"><div class="mb-4"><div class="text-uppercase text-danger fw-bold small">EVENT PRESENTATION</div><h1 class="h2">Live Screen Projector</h1><p class="text-muted">Select the event first. All Judge, Competitor, Scoring, Callback, Finalist and Winner screens remain inside that event.</p></div><?php if($eventId<1):?><div class="row g-3"><?php foreach($events as $e):?><div class="col-lg-6"><div class="card shadow-sm h-100"><div class="card-body"><h2 class="h5"><?=e($e['name'])?></h2><div class="text-muted"><?=e((string)$e['event_date'])?> · <?=(int)$e['round_count']?> competition round(s)</div><a class="btn btn-danger w-100 mt-3" href="?event_id=<?=(int)$e['id']?>">Select Event</a></div></div></div><?php endforeach;?></div><?php else:$selected=array_values(array_filter($events,fn($e)=>(int)$e['id']===$eventId));?><div class="d-flex justify-content-between align-items-center mb-3"><div><div class="small text-muted">SELECTED EVENT</div><h2 class="h4 mb-0"><?=e($selected[0]['name']??'Event')?></h2></div><a class="btn btn-outline-secondary" href="./">Change Event</a></div><div class="row g-3"><?php foreach($rounds as $r):?><div class="col-lg-6"><div class="card shadow-sm h-100"><div class="card-body"><div class="d-flex justify-content-between"><div><h3 class="h5"><?=e(ucwords(str_replace('_',' ',$r['division'])))?></h3><div class="text-muted"><?=e(ucfirst($r['round_type']))?></div></div><span class="badge text-bg-dark"><?=e(strtoupper($r['scoring_mode']??'manual'))?></span></div><a class="btn btn-danger w-100 mt-3" href="control.php?round_id=<?=(int)$r['id']?>">Projection Control</a></div></div></div><?php endforeach;?></div><?php endif;?></main></body></html>